def award_points(guesses: dict[str, str], correct: str, scores: dict[str, int]) -> dict[str, int]:
    if correct not in {'a', 'b', 'tie'}:
        raise ValueError('Correct choice must be one of {a, b, tie}')
    new_scores = dict(scores)
    for user, vote in guesses.items():
        if isinstance(user, bool) or not isinstance(user, str) or not isinstance(vote, str) or not vote in {'a', 'b'}:
            raise TypeError('User must be a string, vote must be one of {a, b}')
        if vote == correct:
            new_scores[user] = scores.get(user, 0) + 100
        elif correct == 'tie':
            new_scores[user] = scores.get(user, 0) + 50
    return new_scores.copy()
